// What the local app's scripts are made of; npm run build:analyze runs it after building. Reads the
// sourcemaps of an analyze build (in .scratch/analyze/, never in dist/) and gives each
// generated byte to the source file it came from, packages grouped by name. Raw minified bytes, before
// gzip: gzip can't be split by source. Prints the top 20 of each script, the entry first, with their
// share of it. No dependency: the mappings' base64 VLQ is decoded here.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { entryFiles } from "./bundle-sizes.ts";

const root = fileURLToPath(new URL("..", import.meta.url));
export const ANALYZE_DIR = join(root, ".scratch", "analyze");

export interface Part { source: string; bytes: number }
export interface Composition { chunk: string; entry: boolean; bytes: number; parts: Part[] }

const BASE64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// One segment of a sourcemap's mappings: its base64 VLQ numbers (each 5 bits a digit, the 6th bit
// "more follows", the lowest bit of the result the sign).
export function decodeVlq(segment: string): number[] {
  const values: number[] = [];
  let value = 0;
  let shift = 0;
  for (const char of segment) {
    const digit = BASE64.indexOf(char);
    if (digit < 0) throw new Error(`not base64 VLQ: ${segment}`);
    value += (digit & 31) * 2 ** shift;
    if (digit & 32) {
      shift += 5;
      continue;
    }
    values.push(value % 2 ? -(value - 1) / 2 : value / 2);
    value = 0;
    shift = 0;
  }
  if (shift) throw new Error(`a VLQ number doesn't end: ${segment}`);
  return values;
}

// A source path as people name it: a package by its name (a scoped one with its scope; the last
// node_modules wins for a nested one), else the path from the repository's root, with /. A path is
// relative to the map's folder, except in a worker's map, where Vite writes it relative to the app's
// root (ui/): that one is used when only it names a file.
export function sourceName(source: string, mapFolder: string): string {
  const path = source.replace(/\\/g, "/");
  const at = path.lastIndexOf("node_modules/");
  if (at >= 0) {
    const [first, second] = path.slice(at + "node_modules/".length).split("/");
    return first.startsWith("@") && second ? `${first}/${second}` : first;
  }
  if (path.startsWith("\0") || /^[a-z]+:/i.test(path)) return path.replace(/^\0/, "");
  const fromMap = resolve(mapFolder, path);
  const fromApp = resolve(root, "ui", path);
  const file = !existsSync(fromMap) && existsSync(fromApp) ? fromApp : fromMap;
  return relative(root, file).split(sep).join("/");
}

// The bytes of `code` each source wrote, by the map's mappings: a segment owns the bytes from its
// column to the next segment's, or the line's end. Bytes no segment names (and the line breaks)
// are "(unmapped)".
export function compose(code: string, map: { sources: string[]; mappings: string }, mapFolder: string): Part[] {
  const lines = code.split("\n");
  const mappings = map.mappings.split(";");
  const names = map.sources.map((source) => sourceName(source, mapFolder));
  const totals = new Map<string, number>();
  const add = (name: string, bytes: number) => bytes && totals.set(name, (totals.get(name) ?? 0) + bytes);
  let source = 0;
  lines.forEach((line, n) => {
    let column = 0;
    let start = 0;
    let owner = "(unmapped)";
    for (const segment of (mappings[n] ?? "").split(",").filter(Boolean)) {
      const fields = decodeVlq(segment);
      column += fields[0];
      add(owner, Buffer.byteLength(line.slice(start, column)));
      if (fields.length >= 4) {
        source += fields[1];
        owner = names[source] ?? "(unmapped)";
      } else owner = "(unmapped)";
      start = column;
    }
    add(owner, Buffer.byteLength(line.slice(start)));
    if (n < lines.length - 1) add("(unmapped)", 1);
  });
  return [...totals].map(([name, bytes]) => ({ source: name, bytes })).sort((a, b) => b.bytes - a.bytes || a.source.localeCompare(b.source));
}

// Each script of a build folder with its map, the ones index.html loads first. Throws for a script
// without its map: the folder isn't an analyze build.
export function composition(folder = ANALYZE_DIR): Composition[] {
  if (!existsSync(join(folder, "index.html"))) throw new Error(`No analyze build in ${relative(root, folder) || folder}. Run npm run build:analyze first.`);
  const entries = new Set(entryFiles(readFileSync(join(folder, "index.html"), "utf8")));
  const scripts = readdirSync(folder).filter((name) => name.endsWith(".js")).sort();
  return scripts
    .map((chunk) => {
      const mapFile = join(folder, `${chunk}.map`);
      if (!existsSync(mapFile)) throw new Error(`${chunk} has no sourcemap: run npm run build:analyze, which builds the app with them.`);
      const code = readFileSync(join(folder, chunk), "utf8");
      const parts = compose(code, JSON.parse(readFileSync(mapFile, "utf8")), dirname(mapFile));
      return { chunk, entry: entries.has(chunk), bytes: Buffer.byteLength(code), parts };
    })
    .sort((a, b) => Number(b.entry) - Number(a.entry) || b.bytes - a.bytes);
}

export function render(chunks: Composition[], top = 20): string[] {
  const kB = (bytes: number) => `${(bytes / 1024).toFixed(1)} kB`.padStart(9);
  const lines: string[] = [];
  for (const { chunk, entry, bytes, parts } of chunks) {
    lines.push(`${chunk}${entry ? " (first files)" : " (lazy)"}: ${kB(bytes).trim()} raw`);
    for (const part of parts.slice(0, top)) lines.push(`${kB(part.bytes)}  ${((100 * part.bytes) / bytes).toFixed(1).padStart(5)} %  ${part.source}`);
    const rest = parts.slice(top);
    if (rest.length) {
      const bytesLeft = rest.reduce((total, part) => total + part.bytes, 0);
      lines.push(`${kB(bytesLeft)}  ${((100 * bytesLeft) / bytes).toFixed(1).padStart(5)} %  ${rest.length} more sources`);
    }
    lines.push("");
  }
  return lines;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    for (const line of render(composition(process.argv[2] ? resolve(process.argv[2]) : ANALYZE_DIR))) console.log(line);
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}
